112	    /**
113	     * Derives the owner's {@code identityKey}, the single key all duplicate detection is expressed
114	     * through: the SHA-256 hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}
115	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
116	     */
117	    default String identityKey(Owner owner) {
118	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
119	                .identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
120	    }
121	
122	    /**
123	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
124	     * humans as the country code, a space, then the national digits grouped left-to-right in threes
125	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The known country codes are
126	     * {@code +61} (2 digits, matching the normalization in
127	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields}) and
128	     * {@code +1} (1 digit); any other leading digit is treated as a two-digit country code. Returns
129	     * {@code null} when the telephone is absent or not a {@code +}-prefixed run of digits, so the raw
130	     * {@code telephone} is left untouched in E.164 form.
131	     */
132	    default String telephoneDisplay(Owner owner) {
133	        String telephone = owner.getTelephone();
134	        if (telephone == null || !telephone.startsWith("+")) {
135	            return null;
136	        }
137	        String digits = telephone.substring(1);
138	        if (!digits.matches("\\d+")) {
139	            return null;
140	        }
141	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
142	        if (digits.length() <= countryCodeLength) {
143	            return null;
144	        }
145	        String countryCode = digits.substring(0, countryCodeLength);
146	        String national = digits.substring(countryCodeLength);
147	        StringBuilder grouped = new StringBuilder();
148	        for (int i = 0; i < national.length(); i++) {
149	            if (i > 0 && i % 3 == 0) {
150	                grouped.append(' ');
151	            }
152	            grouped.append(national.charAt(i));
153	        }
154	        return "+" + countryCode + " " + grouped;
155	    }
156	
157	    /**
158	     * Fixed region-to-timezone table mapping each locality (region) to its IANA timezone name.
159	     */
160	    Map<String, String> REGION_TIMEZONE = Map.of(
161	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
162	
163	    /**
164	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's {@link #locality(Owner)}
165	     * (region) from the fixed region-to-timezone table (NSW→Australia/Sydney, VIC→Australia/Melbourne,
166	     * QLD→Australia/Brisbane). Returns {@code null} when the locality is not in the table (e.g. 'UNKNOWN'),
167	     * so owners outside the known regions map cleanly.
168	     */
169	    default String timezone(Owner owner) {
170	        return REGION_TIMEZONE.get(locality(owner));
171	    }
172	
173	    /**
174	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
175	     * otherwise {@code 'PHONE'}.
176	     */
177	    default String contactPreference(Owner owner) {
178	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
179	        return hasEmail ? "EMAIL" : "PHONE";
180	    }
181	
182	    /**
183	     * Derives the owner's locality (region) from the region-and-hash {@code customerCode}: it is the
184	     * {@code REGION} prefix of {@code '<REGION>-<HASH8>'} (see
185	     * {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}). When the code is
186	     * absent it falls back to computing the region directly from the postcode range (NSW 2000-2099,
187	     * VIC 3000-3099, QLD 4000-4099) then the city table, yielding {@code 'UNKNOWN'} when neither
188	     * resolves. Sharing the region with the identity keeps locality and customerCode consistent.
189	     */
190	    default String locality(Owner owner) {
191	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCode
192	                .regionOf(owner.getCustomerCode());
193	        if (region != null) {
194	            return region;
195	        }
196	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
197	                .region(owner.getPostcode(), owner.getCity());
198	    }
199	
200	    /**
201	     * Derives the owner's membership points: starting at 0, plus 2 when an email is present, plus 1
202	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more (its
203	     * {@code householdMemberCount}), plus 3 when the owner's tenure — the number of fiscal years
204	     * (starting 1 July) elapsed between {@code registrationDate} and today — exceeds 1.
205	     */
206	    static Integer membershipPoints(Owner owner) {
207	        return membershipPoints(owner, owner.getHouseholdMemberCount());
208	    }
209	
210	    /**
211	     * As {@link #membershipPoints(Owner)}, but scoring the "household of 3 or more" bonus against the
212	     * supplied {@code householdMemberCount} rather than the owner's stored one. Used when evaluating an
213	     * existing household member against the household as it stands <em>now</em> (see
214	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}), since a
215	     * member's own count is frozen at its own create time.
216	     */
217	    static Integer membershipPoints(Owner owner, Integer householdMemberCount) {
218	        int points = 0;
219	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
220	        if (hasEmail) {
221	            points += 2;
222	        }
223	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
224	        if (noNamesakes) {
225	            points += 1;
226	        }
227	        boolean largeHousehold = householdMemberCount != null && householdMemberCount >= 3;
228	        if (largeHousehold) {
229	            points += 2;
230	        }
231	        boolean tenured = owner.getRegistrationDate() != null
232	                && (fiscalYearEnding(java.time.LocalDate.now())
233	                        - fiscalYearEnding(owner.getRegistrationDate())) > 1;
234	        if (tenured) {
235	            points += 3;
236	        }
237	        return points;
238	    }
239	
240	    /**
241	     * The owner's effective membership level. When a level has been stored on the entity (assigned at
242	     * create time by
243	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}, which
244	     * applies the household level ceiling) that value stands; otherwise it falls back to the level
245	     * derived directly from points (see {@link #derivedMembershipLevel(Owner)}), so seed owners
246	     * without a stored level still map cleanly.
247	     */
248	    static Integer membershipLevel(Owner owner) {
249	        if (owner.getMembershipLevel() != null) {
250	            return owner.getMembershipLevel();
251	        }
252	        return derivedMembershipLevel(owner);
253	    }
254	
255	    /**
256	     * Derives the owner's membership level from 1 to 4 by mapping {@link #membershipPoints(Owner)}:
257	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. This is the uncapped level, before
258	     * the household ceiling applied at create time.
259	     */
260	    static Integer derivedMembershipLevel(Owner owner) {
261	        return levelForPoints(membershipPoints(owner));
262	    }
263	
264	    /**
265	     * As {@link #derivedMembershipLevel(Owner)}, but scoring the household bonus against the supplied
266	     * {@code householdMemberCount} — the household's current size — rather than the owner's frozen one.
267	     */
268	    static Integer derivedMembershipLevel(Owner owner, Integer householdMemberCount) {
269	        return levelForPoints(membershipPoints(owner, householdMemberCount));
270	    }
271	
272	    private static Integer levelForPoints(int points) {
273	        if (points >= 6) {
274	            return 4;
275	        }
276	        if (points >= 4) {
277	            return 3;
278	        }
279	        if (points >= 2) {
280	            return 2;
281	        }
282	        return 1;
283	    }
284	
285	    /**
286	     * Derives the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
287	     * last two digits of the fiscal year (starting 1 July) that contains the registrationDate — the
288	     * same year segment as {@link #fiscalYear(Owner)} (e.g. {@code 'NSW-1A2B3C4D-M27'} for a
289	     * registrationDate of 15 Aug 2026). Returns {@code null} when either source field is absent, so
290	     * owners without a customerCode or registrationDate map cleanly.
291	     */
292	    default String membershipNumber(Owner owner) {
293	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
294	            return null;
295	        }
296	        return owner.getCustomerCode() + "-M"
297	                + String.format("%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
298	    }
299	
300	    /**
301	     * Derives the owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
302	     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
303	     * absent, so owners without a customerCode map cleanly.
304	     */
305	    default Integer checkDigit(Owner owner) {
306	        String customerCode = owner.getCustomerCode();
307	        if (customerCode == null) {
308	            return null;
309	        }
310	        int sum = 0;
311	        boolean dbl = true;
312	        for (int i = customerCode.length() - 1; i >= 0; i--) {
313	            char c = customerCode.charAt(i);
314	            if (c < '0' || c > '9') {
315	                continue;
316	            }
317	            int d = c - '0';
318	            if (dbl) {
319	                d *= 2;
320	                if (d > 9) {
321	                    d -= 9;
322	                }
323	            }
324	            sum += d;
325	            dbl = !dbl;
326	        }
327	        return (10 - (sum % 10)) % 10;
328	    }
329	
330	    Owner toOwner(OwnerDto ownerDto);
331	
332	    @Mapping(target = "id", ignore = true)
333	    @Mapping(target = "pets", ignore = true)
334	    @Mapping(target = "customerCode", ignore = true)
335	    @Mapping(target = "householdId", ignore = true)
336	    @Mapping(target = "namesakeCount", ignore = true)
337	    @Mapping(target = "householdMemberCount", ignore = true)
338	    @Mapping(target = "possibleDuplicate", ignore = true)
339	    @Mapping(target = "possibleDuplicateOf", ignore = true)
340	    @Mapping(target = "membershipLevel", ignore = true)
341	    @Mapping(target = "deleted", ignore = true)
342	    Owner toOwner(OwnerFieldsDto ownerDto);
343	
344	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
345	
346	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
347	
348	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
349	        OwnerPageDto ownerPageDto = new OwnerPageDto();
350	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
351	        ownerPageDto.setPage(ownerPage.getNumber());
352	        ownerPageDto.setSize(ownerPage.getSize());
353	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
354	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
355	        return ownerPageDto;
356	    }
357	}
